M.ISLAND_PLACEMENTS = {
    { Name = "WestGardenPirateBastion", Asset = "WestGardenPirateBastion", Origin = Vector3.new(-520, 48, 40) },
    { Name = "SunshardSkySanctuary", Asset = "SunshardSkySanctuary", Origin = Vector3.new(540, 88, -40) },
    { Name = "CyberportCafeTradingHub", Asset = "CyberportCafeTradingHub", Origin = Vector3.new(2020, 46, 360) },
    { Name = "PermafrostGarrisonFortress", Asset = "PermafrostGarrisonFortress", Origin = Vector3.new(1960, 56, -180) },
    { Name = "MicrochipAwakeningRaidLab", Asset = "MicrochipAwakeningRaidLab", Origin = Vector3.new(3040, 68, 120) },
    { Name = "GlacialWreckageDangerSea", Asset = "GlacialWreckageDangerSea", Origin = Vector3.new(2980, 44, -440) },
    { Name = "CastleOnTheVoidMansion", Asset = "CastleOnTheVoidMansion", Origin = Vector3.new(-3160, 56, 260) },
    { Name = "UmbralCrystalSanctumForest", Asset = "UmbralCrystalSanctumForest", Origin = Vector3.new(-1920, 60, 240) },
    { Name = "TempleOfTheCoreRaceV4", Asset = "TempleOfTheCoreRaceV4", Origin = Vector3.new(-3160, 96, -320) },
    { Name = "MirageSkyIslandLeviathanAbyss", Asset = "MirageSkyIslandLeviathanAbyss", Origin = Vector3.new(-2540, 68, -680) },
    { Name = "VerdantCrown", Asset = "UmbralCrystalSanctumForest", Origin = Vector3.new(0, 120, -2400) },
    { Name = "EmberforgeWastes", Asset = "WestGardenPirateBastion", Origin = Vector3.new(2400, 120, -2400) },
    { Name = "AbyssalTides", Asset = "MirageSkyIslandLeviathanAbyss", Origin = Vector3.new(-2400, 120, -2400) },
    { Name = "ChronosBastion", Asset = "TempleOfTheCoreRaceV4", Origin = Vector3.new(0, 180, -4200) },
    { Name = "VeilsEnd", Asset = "CastleOnTheVoidMansion", Origin = Vector3.new(0, 260, -5800) },
}

local function buildSanctuaryPlatform(parent, name, origin, radius, accentCol)
    local model = Instance.new("Model")
    model.Name = name .. "_SanctuaryIsland"
    model.Parent = parent

    -- Top walkable marble deck (top at origin.Y)
    local deck = Instance.new("Part")
    deck.Name = name .. "_Floor"
    deck.Shape = Enum.PartType.Cylinder
    deck.Anchored = true
    deck.CanCollide = true
    deck.CanQuery = true
    deck.CanTouch = false
    deck.Material = Enum.Material.Marble
    deck.Color = Color3.fromRGB(232, 226, 214)
    deck.Size = Vector3.new(3.0, radius * 2, radius * 2)
    deck.CFrame = CFrame.new(origin.X, origin.Y - 1.5, origin.Z) * CFrame.Angles(0, 0, math.pi / 2)
    deck.Parent = model

    -- Golden outer rim
    local rim = Instance.new("Part")
    rim.Name = name .. "_GoldRim"
    rim.Shape = Enum.PartType.Cylinder
    rim.Anchored = true
    rim.CanCollide = false
    rim.CanQuery = false
    rim.CanTouch = false
    rim.Material = Enum.Material.Metal
    rim.Color = Color3.fromRGB(238, 192, 78)
    rim.Size = Vector3.new(1.8, radius * 2 + 2.4, radius * 2 + 2.4)
    rim.CFrame = CFrame.new(origin.X, origin.Y - 1.6, origin.Z) * CFrame.Angles(0, 0, math.pi / 2)
    rim.Parent = model

    -- Glowing Aether rune ring
    local glow = Instance.new("Part")
    glow.Name = name .. "_AetherRing"
    glow.Shape = Enum.PartType.Cylinder
    glow.Anchored = true
    glow.CanCollide = false
    glow.CanQuery = false
    glow.CanTouch = false
    glow.Material = Enum.Material.Neon
    glow.Color = accentCol
    glow.Transparency = 0.25
    glow.Size = Vector3.new(0.6, radius * 1.75, radius * 1.75)
    glow.CFrame = CFrame.new(origin.X, origin.Y - 0.25, origin.Z) * CFrame.Angles(0, 0, math.pi / 2)
    glow.Parent = model

    -- Tapered floating sky-rock cliff tiers underneath
    for tier = 1, 3 do
        local r = radius * (1 - tier * 0.22)
        local h = 6.5
        local y = origin.Y - 3.0 - (tier - 0.5) * h
        local rock = Instance.new("Part")
        rock.Name = name .. "_CliffTier" .. tier
        rock.Shape = Enum.PartType.Cylinder
        rock.Anchored = true
        rock.CanCollide = false
        rock.CanQuery = false
        rock.CanTouch = false
        rock.Material = Enum.Material.Slate
        rock.Color = Color3.fromRGB(112 - tier * 10, 118 - tier * 10, 134 - tier * 8)
        rock.Size = Vector3.new(h, r * 2, r * 2)
        rock.CFrame = CFrame.new(origin.X, y, origin.Z) * CFrame.Angles(0, 0, math.pi / 2)
        rock.Parent = model
    end
end

function M.SnapToOpenGround(pos, minClearance)
    local clear = minClearance or 3.2
    for _, isl in ipairs(M.ISLAND_PLACEMENTS) do
        local dx = pos.X - isl.Origin.X
        local dz = pos.Z - isl.Origin.Z
        if math.abs(dx) < 185 and math.abs(dz) < 185 then
            local data = M.ISLAND_ASSETS[isl.Asset]
            if data then
                local function isBlockedAt(lx, lz, gy)
                    for _, o in ipairs(data.obst) do
                        local ox, oy, oz, osx, osy, osz = o[1], o[2], o[3], o[4], o[5], o[6]
                        if (oy + osy * 0.5) > gy + 2.0 and (oy - osy * 0.5) < gy + 12.0 then
                            if math.abs(lx - ox) < (osx * 0.5 + clear) and math.abs(lz - oz) < (osz * 0.5 + clear) then
                                return true
                            end
                        end
                    end
                    return false
                end
                -- Check if current (dx, dz) is already on a ground rect and unblocked
                for _, g in ipairs(data.ground) do
                    local gx, gy, gz, gsx, gsz = g[1], g[2], g[3], g[4], g[5]
                    if math.abs(dx - gx) <= gsx * 0.5 and math.abs(dz - gz) <= gsz * 0.5 then
                        if not isBlockedAt(dx, dz, gy) then
                            return Vector3.new(pos.X, isl.Origin.Y - data.offY + gy, pos.Z)
                        end
                    end
                end
                -- Otherwise search candidate points on ground rects for nearest unblocked spot
                local bestX, bestY, bestZ, bestD2 = dx, data.offY, dz, 1e9
                for _, g in ipairs(data.ground) do
                    local gx, gy, gz, gsx, gsz = g[1], g[2], g[3], g[4], g[5]
                    -- clamp (dx, dz) into this ground rect (inset by 2 studs from edge)
                    local hx = math.max(0, gsx * 0.5 - 2.0)
                    local hz = math.max(0, gsz * 0.5 - 2.0)
                    local cx = math.clamp(dx, gx - hx, gx + hx)
                    local cz = math.clamp(dz, gz - hz, gz + hz)
                    for _, pt in ipairs({{cx, cz}, {gx, gz}}) do
                        local tx, tz = pt[1], pt[2]
                        local d2 = (tx - dx)^2 + (tz - dz)^2
                        if d2 < bestD2 and not isBlockedAt(tx, tz, gy) then
                            bestD2 = d2
                            bestX, bestY, bestZ = tx, gy, tz
                        end
                    end
                end
                return Vector3.new(isl.Origin.X + bestX, isl.Origin.Y - data.offY + bestY, isl.Origin.Z + bestZ)
            end
        end
    end
    return pos
end

function M.Build()
    -- 1. Destroy legacy flat walkable floor models that floated over chasms
    for _, legacyName in ipairs({"VeilsEnd", "VerdantCrown", "ChronosBastion", "EmberforgeWastes", "AbyssalTides"}) do
        local oldM = workspace:FindFirstChild(legacyName)
        if oldM and oldM:IsA("Model") then oldM:Destroy() end
    end
    local gsi = workspace:FindFirstChild("GrandSkyIslands")
    if gsi then
        for _, ch in ipairs(gsi:GetChildren()) do
            if ch.Name:sub(1, 10) == "Collision_" then
                ch:Destroy()
            end
        end
    end

    -- 2. Rebuild GrandSkyIslands_Collision with exact 3D multi-tiered terrain slabs + visible shrine islands + bridges
    local colFolder = workspace:FindFirstChild("GrandSkyIslands_Collision")
    if not colFolder then
        colFolder = Instance.new("Folder")
        colFolder.Name = "GrandSkyIslands_Collision"
        colFolder.Parent = workspace
    else
        colFolder:ClearAllChildren()
    end

    buildSanctuaryPlatform(colFolder, "ZiolesGachaShrine", Vector3.new(-220, 38, 260), 46, Color3.fromRGB(195, 110, 255))
    buildSanctuaryPlatform(colFolder, "AetherShrinesAndRaidConsole", Vector3.new(60, 38, 260), 52, Color3.fromRGB(88, 238, 255))

    local slabIdx = 0
    for _, isl in ipairs(M.ISLAND_PLACEMENTS) do
        local data = M.ISLAND_ASSETS[isl.Asset]
        if data then
            local baseY = isl.Origin.Y - data.offY
            for _, g in ipairs(data.ground) do
                slabIdx += 1
                local p = Instance.new("Part")
                p.Name = isl.Name .. "_T" .. slabIdx
                p.Anchored = true
                p.CanCollide = true
                p.CanQuery = true
                p.CanTouch = false
                p.CastShadow = false
                p.Transparency = 1
                p.Size = Vector3.new(g[4] + 1.2, 4.0, g[5] + 1.2)
                p.Position = Vector3.new(isl.Origin.X + g[1], baseY + g[2] - 2.0, isl.Origin.Z + g[3])
                p.Parent = colFolder
            end
            -- Visible 3D bridge on CastleOnTheVoidMansion (World 12 & World 20) connecting central castle (z=0, y=27.5) to south courtyard (z=36, y=16.0)
            if isl.Asset == "CastleOnTheVoidMansion" then
                for step = 0, 6 do
                    local t = step / 6
                    local lz = -2 + t * 38
                    local ly = 27.5 * (1 - t) + 16.0 * t
                    local bp = Instance.new("Part")
                    bp.Name = isl.Name .. "_VoidBridge_" .. step
                    bp.Anchored = true
                    bp.CanCollide = true
                    bp.CanQuery = true
                    bp.CanTouch = false
                    bp.Material = Enum.Material.Slate
                    bp.Color = Color3.fromRGB(54, 42, 76)
                    bp.Size = Vector3.new(16, 2.4, 7.5)
                    bp.Position = Vector3.new(isl.Origin.X, baseY + ly - 1.2, isl.Origin.Z + lz)
                    bp.Parent = colFolder
                end
            elseif isl.Asset == "MirageSkyIslandLeviathanAbyss" then
                local bp = Instance.new("Part")
                bp.Name = isl.Name .. "_MirageBridge"
                bp.Anchored = true
                bp.CanCollide = true
                bp.CanQuery = true
                bp.CanTouch = false
                bp.Material = Enum.Material.Marble
                bp.Color = Color3.fromRGB(185, 228, 242)
                bp.Size = Vector3.new(38, 2.4, 34)
                bp.Position = Vector3.new(isl.Origin.X, baseY + 23.5 - 1.2, isl.Origin.Z + 3)
                bp.Parent = colFolder
            end
        end
    end

    -- 3. Rebuild Solid3DObstacles with main continent boxes + scale=1.0 island building/pillar/crystal boxes
    local oldObst = workspace:FindFirstChild("Solid3DObstacles")
    if oldObst then oldObst:Destroy() end
    local folder = Instance.new("Folder")
    folder.Name = "Solid3DObstacles"
    local idx = 0
    for _, b in ipairs(M.MAIN_BOXES) do
        idx += 1
        local p = Instance.new("Part")
        p.Name = "Solid3D_" .. idx
        p.Anchored = true
        p.CanCollide = true
        p.CanQuery = true
        p.CanTouch = false
        p.CastShadow = false
        p.Transparency = 1
        p.Size = Vector3.new(b[4], b[5], b[6])
        p.Position = Vector3.new(b[1], b[2], b[3])
        p.Parent = folder
    end
    for _, isl in ipairs(M.ISLAND_PLACEMENTS) do
        local data = M.ISLAND_ASSETS[isl.Asset]
        if data then
            local baseY = isl.Origin.Y - data.offY
            for _, o in ipairs(data.obst) do
                idx += 1
                local p = Instance.new("Part")
                p.Name = "Solid3D_" .. idx
                p.Anchored = true
                p.CanCollide = true
                p.CanQuery = true
                p.CanTouch = false
                p.CastShadow = false
                p.Transparency = 1
                p.Size = Vector3.new(o[4], o[5], o[6])
                p.Position = Vector3.new(isl.Origin.X + o[1], baseY + o[2], isl.Origin.Z + o[3])
                p.Parent = folder
            end
        end
    end
    folder:SetAttribute("SolidColliderCount", idx)
    folder.Parent = workspace
    return folder
end
return M
